insert into public.committees (slug,name,short_desc,about,expect,image_url,image_alt,sort_order) values ($s$unga$s$,$j${"en": "United Nations General Assembly", "ar": "الجمعية العامة للأمم المتحدة", "tr": "Birleşmiş Milletler Genel Kurulu"}$j$::jsonb,$j${"en": "Debate international priorities, build consensus across countries, and draft resolutions addressing shared global challenges.", "ar": "ناقش أولويات المجتمع الدولي، وابنِ التوافق بين الدول، وصُغ مشاريع قرارات تتناول التحديات العالمية المشتركة.", "tr": "Uluslararası öncelikleri tartışın, ülkeler arasında uzlaşı oluşturun ve ortak küresel sorunlara yönelik karar taslakları hazırlayın."}$j$::jsonb,$j${"en": "The General Assembly provides a forum for member states to discuss international issues and express collective priorities.", "ar": "توفّر الجمعية العامة منتدىً تناقش فيه الدول الأعضاء القضايا الدولية وتعبّر عن أولوياتها المشتركة.", "tr": "Genel Kurul, üye devletlerin uluslararası konuları görüşmesi ve ortak önceliklerini dile getirmesi için bir platform sağlar."}$j$::jsonb,$j${"en": "Delegates research their assigned country’s position, deliver speeches, negotiate with other delegations, and work together on draft resolutions.", "ar": "يبحث المندوبون في موقف الدولة المكلَّفين بتمثيلها، ويلقون الكلمات، ويتفاوضون مع الوفود الأخرى، ويعملون معًا على صياغة مشاريع القرارات.", "tr": "Delegeler, kendilerine atanan ülkenin tutumunu araştırır, konuşmalar yapar, diğer heyetlerle müzakere eder ve karar taslakları üzerinde birlikte çalışır."}$j$::jsonb,$s$images/United Nations General Assembly.webp$s$,$j${"en": "United Nations General Assembly emblem", "ar": "شعار الجمعية العامة للأمم المتحدة", "tr": "Birleşmiş Milletler Genel Kurulu amblemi"}$j$::jsonb,0) on conflict (slug) do nothing;
insert into public.committees (slug,name,short_desc,about,expect,image_url,image_alt,sort_order) values ($s$security-council$s$,$j${"en": "United Nations Security Council", "ar": "مجلس الأمن التابع للأمم المتحدة", "tr": "Birleşmiş Milletler Güvenlik Konseyi"}$j$::jsonb,$j${"en": "Examine questions of international peace and security through urgent debate, negotiation, and strategic decision-making.", "ar": "ادرس قضايا السلم والأمن الدوليين من خلال نقاش عاجل وتفاوض واتخاذ قرارات استراتيجية.", "tr": "Uluslararası barış ve güvenlik sorunlarını acil tartışma, müzakere ve stratejik karar alma yoluyla ele alın."}$j$::jsonb,$j${"en": "The Security Council focuses on threats to international peace and security and the diplomatic tools used to address them.", "ar": "يركّز مجلس الأمن على التهديدات التي تواجه السلم والأمن الدوليين وعلى الأدوات الدبلوماسية المستخدمة لمعالجتها.", "tr": "Güvenlik Konseyi, uluslararası barış ve güvenliğe yönelik tehditlere ve bunlarla başa çıkmak için kullanılan diplomatik araçlara odaklanır."}$j$::jsonb,$j${"en": "Participants evaluate a crisis, negotiate possible responses, and develop proposals while considering national interests and international law.", "ar": "يقيّم المشاركون أزمةً ما، ويتفاوضون حول الاستجابات الممكنة، ويطوّرون مقترحات مع مراعاة المصالح الوطنية والقانون الدولي.", "tr": "Katılımcılar bir krizi değerlendirir, olası yanıtlar üzerinde müzakere eder ve ulusal çıkarları ile uluslararası hukuku gözeterek öneriler geliştirir."}$j$::jsonb,$s$images/United Nations Security Council.webp$s$,$j${"en": "United Nations Security Council emblem", "ar": "شعار مجلس الأمن التابع للأمم المتحدة", "tr": "Birleşmiş Milletler Güvenlik Konseyi amblemi"}$j$::jsonb,1) on conflict (slug) do nothing;
insert into public.committees (slug,name,short_desc,about,expect,image_url,image_alt,sort_order) values ($s$oic$s$,$j${"en": "Organisation of Islamic Cooperation", "ar": "منظمة التعاون الإسلامي", "tr": "İslam İşbirliği Teşkilatı"}$j$::jsonb,$j${"en": "Explore cooperation among member states and develop diplomatic responses to issues affecting communities across the world.", "ar": "استكشف التعاون بين الدول الأعضاء وطوّر استجابات دبلوماسية للقضايا التي تمس المجتمعات حول العالم.", "tr": "Üye devletler arasındaki iş birliğini keşfedin ve dünyadaki toplulukları etkileyen sorunlara diplomatik yanıtlar geliştirin."}$j$::jsonb,$j${"en": "The OIC offers a platform for cooperation among its member states on shared political, social, humanitarian, and development concerns.", "ar": "توفّر المنظمة منصة للتعاون بين دولها الأعضاء في القضايا السياسية والاجتماعية والإنسانية والتنموية المشتركة.", "tr": "İİT, üye devletleri arasında ortak siyasi, sosyal, insani ve kalkınmaya ilişkin konularda iş birliği için bir platform sunar."}$j$::jsonb,$j${"en": "Delegates represent national perspectives, build coalitions, and propose practical collaborative initiatives.", "ar": "يمثّل المندوبون وجهات النظر الوطنية، ويبنون التحالفات، ويقترحون مبادرات تعاونية عملية.", "tr": "Delegeler ulusal bakış açılarını temsil eder, koalisyonlar kurar ve uygulanabilir iş birliği girişimleri önerir."}$j$::jsonb,$s$images/Organisation of Islamic Cooperation.webp$s$,$j${"en": "Organisation of Islamic Cooperation emblem", "ar": "شعار منظمة التعاون الإسلامي", "tr": "İslam İşbirliği Teşkilatı amblemi"}$j$::jsonb,2) on conflict (slug) do nothing;
insert into public.committees (slug,name,short_desc,about,expect,image_url,image_alt,sort_order) values ($s$human-rights-council$s$,$j${"en": "Human Rights Council", "ar": "مجلس حقوق الإنسان", "tr": "İnsan Hakları Konseyi"}$j$::jsonb,$j${"en": "Discuss the protection of fundamental freedoms, humanitarian concerns, and practical ways to strengthen human rights.", "ar": "ناقش حماية الحريات الأساسية والشواغل الإنسانية والسبل العملية لتعزيز حقوق الإنسان.", "tr": "Temel özgürlüklerin korunmasını, insani kaygıları ve insan haklarını güçlendirmenin pratik yollarını tartışın."}$j$::jsonb,$j${"en": "The Human Rights Council addresses human-rights situations and considers ways to protect fundamental freedoms and dignity.", "ar": "يتناول المجلس أوضاع حقوق الإنسان وينظر في سبل حماية الحريات الأساسية والكرامة.", "tr": "Konsey, insan hakları durumlarını ele alır ve temel özgürlüklerin ve onurun korunması yollarını değerlendirir."}$j$::jsonb,$j${"en": "Participants assess evidence, discuss international standards, and negotiate recommendations that balance urgency with feasibility.", "ar": "يقيّم المشاركون الأدلة، ويناقشون المعايير الدولية، ويتفاوضون حول توصيات توازن بين الإلحاح وإمكانية التنفيذ.", "tr": "Katılımcılar kanıtları değerlendirir, uluslararası standartları tartışır ve aciliyet ile uygulanabilirlik arasında denge kuran tavsiyeler üzerinde müzakere eder."}$j$::jsonb,$s$images/Human Rights Council.webp$s$,$j${"en": "Human Rights Council emblem", "ar": "شعار مجلس حقوق الإنسان", "tr": "İnsan Hakları Konseyi amblemi"}$j$::jsonb,3) on conflict (slug) do nothing;
insert into public.committees (slug,name,short_desc,about,expect,image_url,image_alt,sort_order) values ($s$who$s$,$j${"en": "World Health Organization", "ar": "منظمة الصحة العالمية", "tr": "Dünya Sağlık Örgütü"}$j$::jsonb,$j${"en": "Consider global public-health challenges and negotiate cooperative policies that improve health, access, and preparedness.", "ar": "تناول تحديات الصحة العامة العالمية وتفاوض حول سياسات تعاونية تحسّن الصحة وإمكانية الحصول على الرعاية والاستعداد للأزمات.", "tr": "Küresel halk sağlığı sorunlarını ele alın ve sağlığı, erişimi ve hazırlıklılığı iyileştiren iş birliğine dayalı politikalar üzerinde müzakere edin."}$j$::jsonb,$j${"en": "The World Health Organization coordinates international public-health efforts and supports cooperation on shared health challenges.", "ar": "تنسّق منظمة الصحة العالمية جهود الصحة العامة الدولية وتدعم التعاون في مواجهة التحديات الصحية المشتركة.", "tr": "Dünya Sağlık Örgütü, uluslararası halk sağlığı çabalarını koordine eder ve ortak sağlık sorunlarında iş birliğini destekler."}$j$::jsonb,$j${"en": "Delegates examine public-health priorities, compare policy approaches, and propose coordinated solutions.", "ar": "يدرس المندوبون أولويات الصحة العامة، ويقارنون بين مقاربات السياسات، ويقترحون حلولًا منسّقة.", "tr": "Delegeler halk sağlığı önceliklerini inceler, politika yaklaşımlarını karşılaştırır ve koordineli çözümler önerir."}$j$::jsonb,$s$images/World Health Organization.webp$s$,$j${"en": "World Health Organization emblem", "ar": "شعار منظمة الصحة العالمية", "tr": "Dünya Sağlık Örgütü amblemi"}$j$::jsonb,4) on conflict (slug) do nothing;
insert into public.committees (slug,name,short_desc,about,expect,image_url,image_alt,sort_order) values ($s$press-corps$s$,$j${"en": "International Press Corps", "ar": "الهيئة الصحفية الدولية", "tr": "Uluslararası Basın Heyeti"}$j$::jsonb,$j${"en": "Report on committee proceedings, interview participants, and tell the story of GDF through responsible media coverage.", "ar": "غطِّ أعمال اللجان، وأجرِ مقابلات مع المشاركين، وروِ قصة GDF عبر تغطية إعلامية مسؤولة.", "tr": "Komite çalışmalarını haberleştirin, katılımcılarla röportaj yapın ve sorumlu medya haberciliğiyle GDF’nin hikâyesini anlatın."}$j$::jsonb,$j${"en": "The International Press Corps documents summit developments and helps participants and audiences understand the debates taking place.", "ar": "توثّق الهيئة الصحفية الدولية مجريات القمة وتساعد المشاركين والجمهور على فهم النقاشات الدائرة.", "tr": "Uluslararası Basın Heyeti zirvedeki gelişmeleri belgeler ve katılımcıların ve izleyicilerin yürütülen tartışmaları anlamasına yardımcı olur."}$j$::jsonb,$j${"en": "Press members may write reports, conduct interviews, capture approved photography, and communicate events accurately and fairly.", "ar": "قد يكتب أعضاء الهيئة الصحفية تقارير، ويجرون مقابلات، ويلتقطون صورًا معتمدة، وينقلون الأحداث بدقة وإنصاف.", "tr": "Basın üyeleri haber yazabilir, röportaj yapabilir, onaylı fotoğraflar çekebilir ve etkinlikleri doğru ve tarafsız biçimde aktarabilir."}$j$::jsonb,$s$images/International Press Corps.webp$s$,$j${"en": "International Press Corps emblem", "ar": "شعار الهيئة الصحفية الدولية", "tr": "Uluslararası Basın Heyeti amblemi"}$j$::jsonb,5) on conflict (slug) do nothing;
insert into public.faqs (question,answer,link_url,link_label,sort_order) values ($j${"en": "When will GDF’27 take place?", "ar": "متى ستُقام GDF'27؟", "tr": "GDF’27 ne zaman gerçekleşecek?"}$j$::jsonb,$j${"en": "GDF’27 is scheduled to take place in March 2027.", "ar": "من المقرر أن يُعقد مؤتمر GDF'27 في مارس 2027.", "tr": "GDF’27’nin Mart 2027’de gerçekleştirilmesi planlanmaktadır."}$j$::jsonb,null,null,0);
insert into public.faqs (question,answer,link_url,link_label,sort_order) values ($j${"en": "Where will the summit be held?", "ar": "أين ستُعقد القمة؟", "tr": "Zirve nerede düzenlenecek?"}$j$::jsonb,$j${"en": "The summit is planned to take place in Gaziantep, Türkiye. Further venue details will be shared through official GDF channels.", "ar": "من المخطط أن تُعقد القمة في غازي عنتاب بتركيا. وستُشارَك تفاصيل المقر عبر قنوات GDF الرسمية.", "tr": "Zirvenin Türkiye’nin Gaziantep kentinde düzenlenmesi planlanmaktadır. Mekâna ilişkin ayrıntılar resmi GDF kanalları üzerinden paylaşılacaktır."}$j$::jsonb,null,null,1);
insert into public.faqs (question,answer,link_url,link_label,sort_order) values ($j${"en": "How can I apply?", "ar": "كيف يمكنني التقديم؟", "tr": "Nasıl başvurabilirim?"}$j$::jsonb,$j${"en": "Visit the Applications page and choose the application type that best matches your role.", "ar": "زر صفحة التقديم واختر نوع الطلب الأنسب لدورك.", "tr": "Başvurular sayfasını ziyaret edin ve rolünüze en uygun başvuru türünü seçin."}$j$::jsonb,$s$applications/$s$,$j${"en": "Explore Applications →", "ar": "استكشف صفحة التقديم ←", "tr": "Başvuruları keşfedin →"}$j$::jsonb,2);
insert into public.faqs (question,answer,link_url,link_label,sort_order) values ($j${"en": "Which committees will be available?", "ar": "ما اللجان المتاحة؟", "tr": "Hangi komiteler olacak?"}$j$::jsonb,$j${"en": "Explore the Committees page for the current list of committees and their areas of focus.", "ar": "تصفّح صفحة اللجان لمعرفة القائمة الحالية للجان ومجالات تركيزها.", "tr": "Mevcut komitelerin listesi ve odak alanları için Komiteler sayfasını inceleyin."}$j$::jsonb,$s$committees/$s$,$j${"en": "Explore Committees →", "ar": "استكشف صفحة اللجان ←", "tr": "Komiteleri keşfedin →"}$j$::jsonb,3);
insert into public.faqs (question,answer,link_url,link_label,sort_order) values ($j${"en": "Who should I contact if I have another question?", "ar": "بمن أتواصل إذا كان لدي سؤال آخر؟", "tr": "Başka bir sorum olursa kiminle iletişime geçmeliyim?"}$j$::jsonb,$j${"en": "You can contact the organizing team using the email address listed in the footer.", "ar": "يمكنك التواصل مع فريق التنظيم عبر البريد الإلكتروني المذكور في أسفل الصفحة.", "tr": "Alt bilgide yer alan e-posta adresini kullanarak organizasyon ekibiyle iletişime geçebilirsiniz."}$j$::jsonb,null,null,4);
